const esc = (value = '') => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const L = (lang, value) => {
  if (!value) return '';
  if (typeof value === 'string') return translatePhrase(lang, value);
  if (value[lang]) return value[lang];
  return translatePhrase(lang, value.en || '');
};

const tx = (lang) => i18n[lang] || i18n.en;

const url = (lang, path = '/') => {
  const clean = path.startsWith('/') ? path : `/${path}`;
  const withSlash = clean.endsWith('/') ? clean : `${clean}/`;
  return `/${lang}${withSlash}`;
};

const slug = (value = '') => String(value)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '') || 'file';

const write = (path, html) => {
  const target = join(ROOT, path);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, html);
};

const publicToFile = (publicPath) => join(ROOT, publicPath.replace(/^\//, ''));

function copyDir(source, target) {
  if (!existsSync(source)) return;
  mkdirSync(target, { recursive: true });
  for (const entry of readdirSync(source)) {
    const from = join(source, entry);
    const to = join(target, entry);
    if (statSync(from).isDirectory()) copyDir(from, to);
    else copyFileSync(from, to);
  }
}

function optimizedImage(id) {
  return imageManifest.images?.[id] || null;
}

function srcset(entries = []) {
  return entries.map(item => `${item.src} ${item.width}w`).join(', ');
}

function responsiveImage(id, alt = '', className = 'responsiveImg', options = {}) {
  const image = optimizedImage(id);
  if (!image) return '';
  const fallback = image.formats?.fallback?.at(-1);
  if (!fallback) return '';
  const loading = options.eager ? 'eager' : 'lazy';
  const priority = options.eager ? 'high' : 'low';
  const sizes = options.sizes || '(max-width: 680px) 100vw, (max-width: 1100px) 80vw, 1200px';
  const webp = image.formats?.webp?.length ? `<source type="image/webp" srcset="${esc(srcset(image.formats.webp))}" sizes="${esc(sizes)}">` : '';
  const fallbackSet = image.formats?.fallback?.length ? srcset(image.formats.fallback) : fallback.src;
  return `<picture>${webp}<img class="${esc(className)}" src="${esc(fallback.src)}" srcset="${esc(fallbackSet)}" sizes="${esc(sizes)}" alt="${esc(alt || image.alt || '')}" width="${image.width}" height="${image.height}" loading="${loading}" decoding="async" fetchpriority="${priority}"></picture>`;
}

function docPublicPath(product, variant, type) {
  const version = variant ? `-${slug(variant.id || L('en', variant.label))}` : '';
  return `/assets/catalogs/${slug(product.id)}${version}-${type}.pdf`;
}

function pdfEscape(value = '') {
  return String(value).replaceAll('\\', '\\\\').replaceAll('(', '\\(').replaceAll(')', '\\)');
}

function writePdf(publicPath, title, subtitle) {
  const target = publicToFile(publicPath);
  mkdirSync(dirname(target), { recursive: true });
  const lines = [
    'SCOR',
    title,
    subtitle,
    'SCOR product and service document.',
    'For detailed quotations and availability, please contact the SCOR team.'
  ];
  const stream = [
    'BT',
    '/F1 34 Tf',
    '72 742 Td',
    `(${pdfEscape(lines[0])}) Tj`,
    '/F1 20 Tf',
    '0 -48 Td',
    `(${pdfEscape(lines[1])}) Tj`,
    '/F1 12 Tf',
    '0 -34 Td',
    `(${pdfEscape(lines[2])}) Tj`,
    '0 -28 Td',
    `(${pdfEscape(lines[3])}) Tj`,
    '0 -22 Td',
    `(${pdfEscape(lines[4])}) Tj`,
    'ET'
  ].join('\n');
  const objects = [
    '1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n',
    '2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n',
    '3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n',
    '4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>\nendobj\n',
    `5 0 obj\n<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream\nendobj\n`
  ];
  let pdf = '%PDF-1.4\n';
  const offsets = [0];
  for (const obj of objects) {
    offsets.push(Buffer.byteLength(pdf));
    pdf += obj;
  }
  const xrefOffset = Buffer.byteLength(pdf);
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += '0000000000 65535 f \n';
  for (let i = 1; i < offsets.length; i++) {
    pdf += `${String(offsets[i]).padStart(10, '0')} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  writeFileSync(target, pdf);
}

function copyBrandAssets() {
  const brandDir = join(ROOT, 'assets/brand');
  mkdirSync(brandDir, { recursive: true });
  const logoSource = join(SRC_ASSETS, 'brand/scor-logo-word.png');
  const paletteSource = join(SRC_ASSETS, 'brand/scor-identity-palette.jpg');
  if (existsSync(logoSource)) copyFileSync(logoSource, join(brandDir, 'scor-logo-word.png'));
  if (existsSync(paletteSource)) copyFileSync(paletteSource, join(brandDir, 'scor-identity-palette.jpg'));
  const appDir = join(ROOT, 'assets/app');
  mkdirSync(appDir, { recursive: true });
  for (const name of ['icon-72.png','icon-96.png','icon-128.png','icon-144.png','icon-152.png','icon-180.png','icon-192.png','icon-384.png','icon-512.png','icon-maskable-512.png']) {
    const source = join(SRC_ASSETS, `app/${name}`);
    if (existsSync(source)) copyFileSync(source, join(appDir, name));
  }
  copyDir(join(SRC_ASSETS, 'media/generated'), join(ROOT, 'assets/media/generated'));
}

function generateDocuments() {
  for (const product of products) {
    if (product.variants?.length) {
      for (const variant of product.variants) {
        writePdf(docPublicPath(product, variant, 'leaflet'), `${product.name} ${L('en', variant.label)} Leaflet`, 'Product leaflet');
        writePdf(docPublicPath(product, variant, 'catalog'), `${product.name} ${L('en', variant.label)} Catalogue`, 'Product catalogue');
      }
    } else {
      writePdf(docPublicPath(product, null, 'leaflet'), `${product.name} Leaflet`, 'Product leaflet');
      writePdf(docPublicPath(product, null, 'catalog'), `${product.name} Catalogue`, 'Product catalogue');
    }
  }
  for (const [groupKey, items] of Object.entries(groups)) {
    for (const item of items) {
      const pseudo = { id: slug(`${groupKey}-${item.id}`) };
      writePdf(docPublicPath(pseudo, null, 'leaflet'), `${groupKey} ${item.id} Leaflet`, 'SCOR information leaflet');
      writePdf(docPublicPath(pseudo, null, 'catalog'), `${groupKey} ${item.id} Catalogue`, 'SCOR information document');
    }
  }
}

