document.querySelectorAll('[data-lang-picker]').forEach(picker=>{const btn=picker.querySelector('[data-lang-toggle]');if(!btn)return;btn.addEventListener('click',e=>{e.stopPropagation();const open=picker.classList.toggle('open');btn.setAttribute('aria-expanded',open?'true':'false')});picker.addEventListener('click',e=>e.stopPropagation());document.addEventListener('click',()=>{picker.classList.remove('open');btn.setAttribute('aria-expanded','false')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){picker.classList.remove('open');btn.setAttribute('aria-expanded','false')}})});
const slider=document.querySelector('[data-slider]');if(slider){const slides=[...slider.querySelectorAll('.slide')];const dots=[...slider.querySelectorAll('[data-slide]')];let current=0;function show(index){slides.forEach((s,i)=>s.classList.toggle('active',i===index));dots.forEach((d,i)=>d.classList.toggle('active',i===index));current=index}dots.forEach(d=>d.addEventListener('click',()=>show(Number(d.dataset.slide))));if(slides.length>1)setInterval(()=>show((current+1)%slides.length),5500)}
document.querySelectorAll('[data-contact-form]').forEach(form=>{const data=form.querySelector('[data-contact-options]');let cfg={typePrompt:'Subject Type',categoryPrompt:'Subject Category',types:[],categories:{}};try{if(data)cfg=JSON.parse(data.textContent||'{}')}catch(error){console.warn(error)}const typeBox=form.querySelector('[data-custom-select="type"]');const catBox=form.querySelector('[data-custom-select="category"]');function closeAll(except){form.querySelectorAll('[data-custom-select]').forEach(box=>{if(box!==except){box.classList.remove('open');const btn=box.querySelector('[data-select-button]');if(btn)btn.setAttribute('aria-expanded','false')}})}function setDisabled(box,disabled){if(!box)return;box.classList.toggle('disabled',!!disabled);const btn=box.querySelector('[data-select-button]');if(btn){btn.disabled=!!disabled;btn.setAttribute('aria-disabled',disabled?'true':'false')}}function setValue(box,value,label){if(!box)return;const input=box.querySelector('[data-select-value]');const btn=box.querySelector('[data-select-button]');if(input)input.value=value||'';if(btn)btn.textContent=label||box.dataset.prompt||'';box.querySelectorAll('[data-select-option]').forEach(o=>o.classList.toggle('selected',o.dataset.value===value))}function fillOptions(box,items,onPick){if(!box)return;const menu=box.querySelector('[data-select-menu]');if(!menu)return;menu.innerHTML='';items.forEach(item=>{const b=document.createElement('button');b.type='button';b.className='selectOption';b.dataset.selectOption='';b.dataset.value=item.value;b.textContent=item.label;b.setAttribute('role','option');b.addEventListener('click',()=>{setValue(box,item.value,item.label);box.classList.remove('open');const btn=box.querySelector('[data-select-button]');if(btn){btn.setAttribute('aria-expanded','false');btn.focus()}if(onPick)onPick(item)});menu.appendChild(b)})}function resetCategory(){if(!catBox)return;setValue(catBox,'',cfg.categoryPrompt||'');fillOptions(catBox,[],null);setDisabled(catBox,true)}function fillCategory(typeValue){resetCategory();const list=(cfg.categories||{})[typeValue]||[];if(list.length){setDisabled(catBox,false);fillOptions(catBox,list.map(label=>({value:label,label})),null)}}fillOptions(typeBox,(cfg.types||[]).map(x=>({value:x.value,label:x.label})),item=>{fillCategory(item.value)});setValue(typeBox,'',cfg.typePrompt||'');resetCategory();form.querySelectorAll('[data-custom-select]').forEach(box=>{const btn=box.querySelector('[data-select-button]');if(!btn)return;btn.addEventListener('click',()=>{if(box.classList.contains('disabled'))return;const open=box.classList.contains('open');closeAll(box);box.classList.toggle('open',!open);btn.setAttribute('aria-expanded',!open?'true':'false')});btn.addEventListener('keydown',e=>{if(e.key==='Escape'){box.classList.remove('open');btn.setAttribute('aria-expanded','false')}})});document.addEventListener('click',e=>{if(!form.contains(e.target))closeAll()});form.__resetContactCategories=()=>{setValue(typeBox,'',cfg.typePrompt||'');resetCategory();closeAll()}});
document.querySelectorAll('[data-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const invalid=[...form.querySelectorAll('[data-select-value]')].find(input=>!input.value);if(invalid){const box=invalid.closest('[data-custom-select]');const btn=box&&box.querySelector('[data-select-button]');if(btn){btn.focus();box.classList.add('invalid');setTimeout(()=>box.classList.remove('invalid'),1200)}return}const msg=form.querySelector('[data-form-msg]');if(msg){msg.textContent=document.body.dataset.formDone||'Request captured.';msg.style.color='#039855'}form.reset();if(form.__resetContactCategories)form.__resetContactCategories()}));
const raw=document.getElementById('variantData');if(raw){try{const variants=JSON.parse(raw.textContent||'[]');const title=document.getElementById('variantTitle');const summary=document.getElementById('variantSummary');const specs=document.getElementById('variantSpecs');const catalog=document.getElementById('variantCatalog');const leaflet=document.getElementById('variantLeaflet');const download=document.body.dataset.download||'download';function setDoc(el,url,label){if(!el)return;el.textContent=label;el.href=url;el.setAttribute('download','');el.dataset.status=download}document.querySelectorAll('[data-variant-index]').forEach(btn=>btn.addEventListener('click',()=>{const v=variants[Number(btn.dataset.variantIndex)];if(!v)return;document.querySelectorAll('[data-variant-index]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');if(title)title.textContent=v.label||'';if(summary)summary.textContent=v.suffix||'';if(specs)specs.innerHTML=Object.entries(v.specs||{}).map(([key,val])=>'<tr><th>'+key+'</th><td>'+val+'</td></tr>').join('');setDoc(leaflet,v.leaflet,'PDF '+(v.label||'')+' Leaflet');setDoc(catalog,v.catalog,'PDF '+(v.label||'')+' Catalogue')}))}catch(error){console.warn(error)}}

