function logoMarkup(className = '') {
  return `<img class="logoWord ${className}" src="${LOGO_PATH}" alt="${esc(brand.name)}">`;
}

function layout(lang, title, description, currentPath, active, body) {
  const t = tx(lang);
  const pageTitle = title === brand.name ? brand.name : `${title} | ${brand.name}`;
  return `<!doctype html><html lang="${lang}" dir="${languages[lang].dir}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(pageTitle)}</title><meta name="description" content="${esc(description || t.meta.description)}">${pwaHead(lang)}<style>${css}</style></head><body data-form-done="${esc(t.common.formDone)}" data-download="${esc(t.common.download)}"><a class="skip" href="#content">Skip to content</a>${header(lang,currentPath,active)}<main id="content">${body}</main>${footer(lang)}<script>${js}</script></body></html>`;
}

function navDropdown(lang, key, items, active) {
  const t = tx(lang);
  return `<div class="navitem ${active === key ? 'active' : ''}"><a href="${url(lang, `/${key}`)}">${esc(t.nav[key])}<span>⌄</span></a><div class="drop">${items.map(item => `<a href="${item.href}"><b>${esc(item.title)}</b>${item.sub ? `<small>${esc(item.sub)}</small>` : '<small>&nbsp;</small>'}</a>`).join('')}</div></div>`;
}

function header(lang, currentPath, active) {
  const t = tx(lang);
  const productItems = categories.map(c => ({ title: L(lang,c.name), sub: L(lang,c.tag), href: url(lang, `/products/${c.id}`) }));
  const groupItems = (key) => groups[key].map(item => ({ title: L(lang,item.title), href: url(lang, `/${key}/${item.id}`) }));
  const switchLinks = languageKeys.map(code => `<a class="${code === lang ? 'active' : ''}" href="/${code}${currentPath}"><span>${languages[code].label}</span><em>${esc(languages[code].name)}</em></a>`).join('');
  return `<header class="top"><div class="topline"><div class="container topbar"><span class="topnote">INDUSTRIAL POWER</span><div class="langTop languagePicker" data-lang-picker aria-label="Language switcher"><button class="globeBtn" type="button" data-lang-toggle aria-expanded="false" aria-label="Language"><span class="globeIcon">🌐</span><b>${languages[lang].label}</b></button><div class="languageMenu" data-lang-menu>${switchLinks}</div></div></div></div><div class="container toprow"><a class="brand" href="${url(lang)}">${logoMarkup()}</a><button class="menu" data-menu aria-label="Menu" aria-expanded="false">☰</button><nav class="nav" data-nav>${navDropdown(lang,'products',productItems,active)}${navDropdown(lang,'production',groupItems('production'),active)}${navDropdown(lang,'services',groupItems('services'),active)}${navDropdown(lang,'corporate',groupItems('corporate'),active)}${navDropdown(lang,'news',groupItems('news'),active)}<a class="navlink ${active === 'contact' ? 'active' : ''}" href="${url(lang,'/contact')}">${esc(t.nav.contact)}</a></nav></div></header>`;
}

function legalLinks(lang) {
  const labelsByLang = {
    en: { privacy:'Privacy Policy', terms:'Terms', imprint:'Imprint' },
    ar: { privacy:'سياسة الخصوصية', terms:'الشروط', imprint:'معلومات الشركة' },
    de: { privacy:'Datenschutz', terms:'Bedingungen', imprint:'Impressum' },
    tr: { privacy:'Gizlilik', terms:'Şartlar', imprint:'Künye' }
  };
  const labels = labelsByLang[lang] || labelsByLang.en;
  return `<span class="legalLinks"><a href="${url(lang,'/legal/privacy-policy')}">${esc(labels.privacy)}</a><span>·</span><a href="${url(lang,'/legal/terms-and-conditions')}">${esc(labels.terms)}</a><span>·</span><a href="${url(lang,'/legal/imprint')}">${esc(labels.imprint)}</a></span>`;
}

function footer(lang) {
  const t = tx(lang);
  return `<footer class="scorFoot"><div class="container scorFootGrid"><div class="footAbout"><a class="brand footLogo" href="${url(lang)}">${logoMarkup()}</a><p>${esc(t.footer.about)}</p><div class="footBadges"><span>${esc(t.common.catalogReady)}</span><span>${esc(t.common.multiLanguage)}</span><span>${esc(t.common.apiReady)}</span></div></div><div class="footContact"><h3>${esc(t.footer.contactTitle)}</h3><p><b>${esc(t.footer.email)}:</b> <a href="${officialContact.emailHref}">${officialContact.email}</a></p><p><b>${esc(t.footer.phone)}:</b> <a href="${officialContact.phoneHref}">${officialContact.phone}</a></p><p><b>${esc(t.footer.location)}:</b> ${esc(L(lang,officialContact.address))}</p><a class="btn" href="${url(lang,'/contact')}">${esc(t.common.request)}</a></div><div class="footActions"><h3>${esc(t.footer.quick)}</h3><a href="${url(lang,'/products')}">${esc(t.footer.browse)}</a><a href="${url(lang,'/contact')}">${esc(t.common.request)}</a><a href="${url(lang,'/contact/global-points')}">${esc(t.common.dealer)}</a><a href="${url(lang,'/legal/terms-and-conditions')}">${esc(lang === 'ar' ? 'الشروط' : lang === 'de' ? 'Bedingungen' : lang === 'tr' ? 'Şartlar' : 'Terms')}</a></div></div><div class="container copy"><span>© ${brand.year} ${brand.name}. ${esc(t.footer.rights)}</span>${legalLinks(lang)}</div></footer>`;
}
function pageHero(lang, title) {
  const t = tx(lang);
  return `<section class="pagehero"><div class="container"><h1>${esc(title)}</h1><div class="crumb"><a href="${url(lang)}">${esc(t.common.home)}</a><span>::</span><b>${esc(title)}</b></div></div></section>`;
}

function categoryCard(lang, c) {
  return `<a class="cat" href="${url(lang, `/products/${c.id}`)}"><div class="catmedia">${machine(c.machine)}</div><h3>${esc(L(lang,c.name))}</h3><p>${esc(L(lang,c.tag))}</p></a>`;
}

function agreementText(lang) {
  if (lang === 'ar') return `أوافق على <a href="${url(lang,'/legal/privacy-policy')}">سياسة الخصوصية</a> و <a href="${url(lang,'/legal/terms-and-conditions')}">الشروط العامة</a>.`;
  if (lang === 'de') return `Ich stimme der <a href="${url(lang,'/legal/privacy-policy')}">Datenschutzerklärung</a> und den <a href="${url(lang,'/legal/terms-and-conditions')}">Nutzungsbedingungen</a> zu.`;
  if (lang === 'tr') return `<a href="${url(lang,'/legal/privacy-policy')}">Gizlilik politikasını</a> ve genel <a href="${url(lang,'/legal/terms-and-conditions')}">kullanım şartlarını</a> kabul ediyorum.`;
  return `I agree <a href="${url(lang,'/legal/privacy-policy')}">privacy policy</a> and general <a href="${url(lang,'/legal/terms-and-conditions')}">terms of use</a>.`;
}

function customSelectMarkup(kind, label, prompt, inputName) {
  return `<div class="customField"><span class="fieldLabel">${esc(label)}</span><div class="customSelect" data-custom-select="${kind}" data-prompt="${esc(prompt)}"><button class="selectBtn" type="button" data-select-button aria-haspopup="listbox" aria-expanded="false">${esc(prompt)}</button><input class="selectNativeValue" data-select-value name="${esc(inputName)}" tabindex="-1" aria-hidden="true"><div class="selectMenu" data-select-menu role="listbox"></div></div></div>`;
}

function contactBlock(lang) {
  const t = tx(lang);
  const options = contactFormOptions[lang] || contactFormOptions.en;
  const optionsJson = JSON.stringify(options).replaceAll('<','\\u003c');
  return `<section class="contact"><div class="container"><h2>${esc(t.home.reach)}</h2><form data-form data-contact-form><label>${esc(t.form.name)}<input name="name" required autocomplete="name"></label><label>${esc(t.form.phone)}<input name="phone" autocomplete="tel"></label><label>${esc(t.form.email)}<input name="email" type="email" required autocomplete="email"></label>${customSelectMarkup('type', t.form.subjectType, options.typePrompt, 'subjectType')}${customSelectMarkup('category', t.form.subjectCategory, options.categoryPrompt, 'subjectCategory')}<label class="full">${esc(t.form.message)}<textarea name="message" rows="4" required></textarea></label><label class="check full"><input type="checkbox" required> <span>${agreementText(lang)}</span></label><div class="formActions full"><button class="btn" type="submit">${esc(t.common.send)}</button><a class="btn outline" href="${url(lang,'/contact/international-corporations')}">${esc(t.common.contact)}</a><a class="btn outline" href="${url(lang,'/contact/global-points')}">${esc(t.common.dealer)}</a></div><p class="msg full" data-form-msg></p><script type="application/json" data-contact-options>${optionsJson}</script></form></div></section>`;
}
function homePage(lang) {
  const t = tx(lang);
  const slides = activities;
  const body = `<section class="hero" data-slider>${slides.map((a,i) => `<article class="slide ${i === 0 ? 'active' : ''}"><div class="container slidein"><div class="slidetext"><span>${esc(L(lang,a.eyebrow))}</span><h1>${esc(L(lang,a.title))}</h1><p>${esc(L(lang,a.tag))}</p><a class="btn" href="${url(lang, a.link)}">${esc(t.common.learn)}</a></div><div class="machwrap">${machine(a.visual)}</div></div></article>`).join('')}<div class="dots">${slides.map((_,i) => `<button class="${i === 0 ? 'active' : ''}" data-slide="${i}" aria-label="Slide ${i+1}"></button>`).join('')}</div></section><section class="section soft"><div class="container"><div class="head"><div><h2>${esc(t.nav.products)}</h2><p>${esc(t.home.productsIntro)}</p></div></div><div class="catgrid">${categories.map(c => categoryCard(lang,c)).join('')}</div></div></section><section class="infotiles"><div class="container"><a class="tile" href="${url(lang,'/production/design-studio')}"><div><b>${esc(t.home.design)}</b><p>${esc(t.common.supportText)}</p><span>${esc(t.common.learn)}</span></div></a><a class="tile" href="${url(lang,'/services/service')}"><div><b>${esc(t.home.service)}</b><p>${esc(t.common.supportText)}</p><span>${esc(t.common.learn)}</span></div></a><a class="tile" href="${url(lang,'/corporate/human-resources')}"><div><b>${esc(t.home.hr)}</b><p>${esc(t.common.supportText)}</p><span>${esc(t.common.learn)}</span></div></a></div></section><section class="section"><div class="container"><div class="head center"><h2>${esc(t.home.awards)}</h2></div><div class="awardrow">${awards.map(a => `<a href="${url(lang,'/corporate/awards')}">${esc(a)}</a>`).join('')}</div></div></section>${contactBlock(lang)}`;
  return layout(lang, brand.name, t.meta.description, '/', 'home', body);
}

function productsIndexPage(lang) {
  const t = tx(lang);
  const body = `${pageHero(lang,t.nav.products)}<section class="section soft"><div class="container"><div class="head"><div><h2>${esc(t.nav.products)}</h2><p>${esc(t.home.productsIntro)}</p></div></div><div class="catgrid">${categories.map(c => categoryCard(lang,c)).join('')}</div></div></section>${contactBlock(lang)}`;
  return layout(lang, t.nav.products, t.meta.description, '/products/', 'products', body);
}

function localizeSpecMap(lang, specs = {}) {
  return Object.fromEntries(Object.entries(specs || {}).map(([key,value]) => [translatePhrase(lang, key), translatePhrase(lang, String(value))]));
}

function miniSpecs(lang, product) {
  const first = product.variants?.[0];
  return Object.entries(localizeSpecMap(lang, first?.specs || product.specs || {})).slice(0,4);
}

function productCard(lang, product) {
  const c = categories.find(cat => cat.id === product.category);
  const specs = miniSpecs(lang, product);
  return `<a class="prod" href="${url(lang, `/products/${product.category}/${product.id}`)}"><div class="prodmedia">${machine(c?.machine)}</div><div class="prodcopy"><small>${esc(c ? L(lang,c.name) : '')}</small><h3>${esc(product.name)}</h3><div class="minispecs">${specs.map(([k,v]) => `<span><b>${esc(k)}</b>${esc(v)}</span>`).join('')}</div></div></a>`;
}

function categoryPage(lang, category) {
  const t = tx(lang);
  const list = products.filter(p => p.category === category.id);
  const countText = `${list.length} ${list.length === 1 ? t.common.modelAvailable : t.common.modelsAvailable}`;
  const body = `${pageHero(lang,L(lang,category.name))}<section class="detail"><div class="container two"><div class="visual">${machine(category.machine)}</div><div><h2>${esc(L(lang,category.tag))}</h2><p>${esc(countText)}</p><a class="btn" href="${url(lang,'/contact')}">${esc(t.common.contact)}</a></div></div><div class="container productlist">${list.length ? list.map(p => productCard(lang,p)).join('') : `<div class="article">${esc(t.common.supportText)}</div>`}</div></section>${contactBlock(lang)}`;
  return layout(lang, L(lang,category.name), L(lang,category.tag), `/products/${category.id}/`, 'products', body);
}

function localizedVariant(lang, product, variant) {
  return {
    id: variant.id,
    label: L(lang, variant.label),
    suffix: L(lang, variant.suffix),
    specs: localizeSpecMap(lang, variant.specs || {}),
    catalog: variant.catalog || docPublicPath(product, variant, 'catalog'),
    leaflet: variant.leaflet || docPublicPath(product, variant, 'leaflet')
  };
}

function productPage(lang, product) {
  const t = tx(lang);
  const category = categories.find(c => c.id === product.category);
  const variants = (product.variants || []).map(v => localizedVariant(lang,product,v));
  const hasVariants = variants.length > 0;
  const first = hasVariants ? variants[0] : null;
  const shownTitle = first ? first.label : product.name;
  const shownSummary = first ? first.suffix : L(lang, product.summary);
  const specs = Object.entries(first?.specs || localizeSpecMap(lang, product.specs || {}));
  const leafletHref = first?.leaflet || product.leaflet || docPublicPath(product, null, 'leaflet');
  const catalogHref = first?.catalog || product.catalog || docPublicPath(product, null, 'catalog');
  const variantBox = hasVariants ? `<div class="variantbox"><h3>${esc(t.common.choose)}</h3><div class="variantbuttons">${variants.map((v,i) => `<button class="variantbtn ${i === 0 ? 'active' : ''}" type="button" data-variant-index="${i}">${esc(v.label)}</button>`).join('')}</div><p class="variantnote">${esc(L(lang, product.summary))}</p></div>` : '';
  const docs = `<div class="docpanel"><div class="docgroup"><span>${esc(t.common.leaflets)}</span><a id="variantLeaflet" class="docbtn" href="${leafletHref}" download data-status="${esc(t.common.download)}">PDF ${esc(shownTitle)} Leaflet</a></div><div class="docgroup"><span>${esc(t.common.catalogs)}</span><a id="variantCatalog" class="docbtn" href="${catalogHref}" download data-status="${esc(t.common.download)}">PDF ${esc(shownTitle)} Catalogue</a></div></div>`;
  const body = `${pageHero(lang,product.name)}<section class="detail"><div class="container two"><div class="visual productvisual">${machine(category?.machine)}${variantBox}</div><div><small style="color:var(--gold);font-weight:1000;text-transform:uppercase">${esc(category ? L(lang,category.name) : '')}</small><h2 id="variantTitle">${esc(shownTitle)}</h2><p id="variantSummary">${esc(shownSummary)}</p>${docs}<a class="btn" href="${url(lang,'/contact')}">${esc(t.common.request)}</a></div></div><div class="container specwrap"><h2>${esc(t.common.technical)}</h2><table class="spectable"><tbody id="variantSpecs">${specs.map(([k,v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div>${hasVariants ? `<script type="application/json" id="variantData">${JSON.stringify(variants).replaceAll('<','\\u003c')}</script>` : ''}</section>${contactBlock(lang)}`;
  return layout(lang, product.name, `${product.name} ${t.common.technical}`, `/products/${product.category}/${product.id}/`, 'products', body);
}



